def find_nth_good_integer(N: int) -> int:
    def generate_good_integer(index: int) -> int:
        digits = []
        while index > 0:
            index, remainder = divmod(index, 5)
            digits.append(str(remainder * 2))
        return int(''.join(reversed(digits)))

    return generate_good_integer(N - 1)
